        "question": "Extended response question on nutrition and meal planning",
        "marks": 80,
        "model": "Carbohydrates provide 50% of daily calories; simple sugars give quick energy while complex carbohydrates from wholegrains provide sustained energy and fibre. Proteins build tissues; meat, fish, eggs, dairy, and legumes provide essential amino acids. Fats enable vitamin absorption; fish and nuts contain healthier unsaturated fats. Vitamins C and A support immunity and vision; B vitamins release energy; D supports bones. Minerals including calcium, iron, and iodine regulate body functions. Water regulates temperature and aids digestion. For John, increasing fruits, vegetables, water, and exercise while reducing fried and processed foods would improve health. Balanced breakfast combining protein, carbohydrates, and fruit provides sustained energy and concentration.",
