        "label": "B2",
        "question": "Extended response question on food preparation",
        "marks": 50,
        "model": "Cooking methods affect food quality and nutrients. Dry methods—roasting, baking, grilling—use direct heat. Roasting creates appealing colours through Maillard reactions suitable for meat and vegetables. Baking requires precise temperatures essential for breads and cakes. Grilling cooks quickly creating appealing textures. Frying increases fat content significantly. Wet methods—boiling, steaming, poaching, stewing—use liquid. Boiling leaches water-soluble nutrients; steaming preserves nutrients better. Poaching gently cooks delicate foods; stewing tenderizes economical meat cuts. Microwave cooking provides convenience but potentially uneven results. Combination braising methods exist. Choosing methods based on nutritional goals optimizes meal quality and appeal.",
        "diagram": "",
