      {
        "label": "B4",
        "question": "Extended response question on budgeting",
        "marks": 50,
        "model": "Budgeting allocates limited resources to meet family needs and goals. Fixed expenses including rent, utilities, and insurance remain constant. Variable expenses including food and entertainment fluctuate. Total income from wages and benefits must cover all expenses. Essential expenses—housing, utilities, food, transport, insurance—take priority. Non-essential spending follows. Emergency funds containing three to six months expenses manage unexpected situations. Monthly reviews identify variances. Adjustments redirect spending when income decreases or expenses increase. Saving for specific goals requires consistent allocation. Children benefit from pocket money teaching budgeting. Poor budgeting causes overspending, debt, and stress. Effective budgeting enables living within means, achieving goals, and financial security. Digital tools including spreadsheets facilitate tracking. Budgeting discipline creates family stability.",
        "diagram": "",
        "model_source": "ai-h1"
      }
