        "question": "Extended response question on family and wellbeing",
        "marks": 50,
        "model": "Health encompasses physical, mental, social, and environmental dimensions. Nutrition from balanced diets prevents deficiency diseases and chronic conditions. Adequate protein, carbohydrates, fats, vitamins, minerals, and water maintain body functions. Regular physical activity of 30 minutes daily maintains cardiovascular health and healthy weight. Exercise improves mental health and sleep quality. Adequate sleep of 7-9 hours nightly enables restoration. Stress management through exercise and relaxation prevents stress-related illness. Social relationships provide emotional support and reduce mortality risk. Avoiding harmful substances including smoking and excess alcohol protects health. Mental health support when needed is essential. Reproductive health, dental hygiene, and health screening enable prevention. Environmental factors including housing, water, and air quality affect health. Education and employment provide security and satisfaction. Holistic health management promotes optimal wellbeing.",
