        "question": "Elective 1: Home Design and Management",
        "marks": 80,
        "model": "Housing provides shelter and family meeting place. Types include detached houses offering privacy, semi-detached and terraced providing affordability, bungalows for elderly avoiding stairs, and apartments for small households. Choice depends on family size, composition, lifestyle, finances, health, and life stage. Young professionals need work-convenient affordable housing. Young families need space, safety, and school access. Teenagers benefit from separate bedrooms. Older adults prefer accessible properties requiring minimal maintenance. Retirees prioritize lower running costs. Urban housing offers convenience but higher costs; rural housing costs less but requires car dependency; suburban balances factors. Housing quality affects health through temperature control, moisture management, natural light, and adequate space. Poor housing causes respiratory disease and mental health problems. Overcrowding impacts relationships and education. Planning housing assesses current suitability and future needs. Sustainable housing minimizes environmental impact. Community facilities affect desirability. Adequate housing is a human right promoting health and opportunity.",
