        "question": "Elective 2: Textiles, Fashion and Design",
        "marks": 40,
        "model": "Textiles from natural and synthetic fibres serve varied purposes. Natural fibres include cotton—breathable and absorbent; linen—strong and durable; silk—soft and lustrous; wool—warm and elastic. Synthetic fibres include polyester—durable and easy-care; acrylic—affordable wool substitute; nylon—strong and elastic; elastane—provides stretch. Blends combine advantages; cotton-polyester combines breathability with wrinkle-resistance. Important properties include durability for longevity, absorbency for comfort, elasticity for movement, crease-resistance for appearance, and flame resistance for safety. Thermal properties including insulation and breathability affect comfort. Aesthetic properties including colour and texture contribute to appeal. Care instructions affect longevity and appearance. Sustainable textiles using organic fibres and ethical production minimize environmental impact. Understanding fibre properties enables selecting appropriate materials for specific uses.",
