        "label": "A1",
        "question": "Name two methods by which protein can be denatured and give an example in each case",
        "marks": 6,
        "model": "Protein is an essential nutrient composed of amino acids linked by peptide bonds. It performs multiple vital functions: builds and repairs body tissues including muscles, bones and organs; forms enzymes which catalyze biochemical reactions; produces hormones regulating body functions; creates antibodies for immune defense; provides energy (4 calories per gram). Proteins are classified as complete (containing all essential amino acids) or incomplete (lacking some essential amino acids). Sources of protein include meat, fish, eggs, dairy products, legumes, nuts and grains. The body cannot manufacture nine essential amino acids, so dietary protein is essential.",
