        "label": "A4",
        "question": "In relation to eggs explain each of the following: (i) Albumin (ii) Lecithin",
        "marks": 6,
        "model": "Fats are essential nutrients composed of fatty acids and glycerol. They are classified into saturated fatty acids (solid at room temperature, found mainly in animal products) and unsaturated fatty acids (liquid at room temperature, found mainly in plant products). Functions include: providing concentrated energy (9 calories per gram); forming cell membranes; absorbing fat-soluble vitamins A, D, E and K; insulating the body and protecting organs; producing certain hormones. Excessive saturated fat consumption is linked to elevated blood cholesterol and increased heart disease risk. Unsaturated fats, particularly polyunsaturated (omega-3 and omega-6) and monounsaturated fats, are considered healthier and may help reduce cardiovascular disease risk. Current dietary recommendations suggest limiting total fat intake to approximately 30-35% of daily calories, with emphasis on unsaturated fat sources.",
