        "label": "A5",
        "question": "Name A, B and C as shown on the diagram of a bacterial cell",
        "marks": 6,
        "model": "Minerals are inorganic substances essential for numerous body functions. Key minerals include: calcium (builds bones and teeth, muscle function); iron (oxygen transport in blood); phosphorus (bone structure, energy metabolism); potassium (nerve function, heart rhythm); magnesium (muscle and nerve function, protein synthesis); sodium (nerve transmission, fluid balance); zinc (immune function, wound healing); iodine (thyroid function); selenium (antioxidant protection). Minerals are present in foods in small quantities but are vital for health. Unlike vitamins, minerals cannot be manufactured by the body and must be obtained from dietary sources. Minerals work in conjunction with vitamins to support metabolic processes. Deficiencies in specific minerals can cause serious health conditions such as anaemia (iron deficiency), goitre (iodine deficiency) or osteoporosis (calcium deficiency).",
        "diagram": "exam-images/home-economics/2007-HL-A5.png",
