    "year": 2007,
    "parts": [
      {
        "label": "A7",
        "question": "State two different functions of An Bord Bia (Irish Food Board) in the Irish Food Industry",
        "marks": 6,
        "model": "Water is the most abundant nutrient in the human body, comprising approximately 60% of adult body weight. Water serves critical functions: transport medium for nutrients and oxygen to cells; removal of waste products through urine; regulation of body temperature through perspiration; lubrication of joints and protection of organs; component of all body fluids. Daily water requirements vary based on age, gender, activity level and climate, with recommendations typically 1.5-2 litres daily. Sources of water include drinking water, beverages including tea and juice, and water content in foods particularly fruits and vegetables. Adequate hydration maintains physiological function, cognitive performance and physical endurance. Dehydration impairs mental and physical performance and can be dangerous. Individual needs are higher during exercise, in hot climates and for certain populations. Water balance is maintained through intake and excretion mechanisms regulated by thirst and hormones.",
        "diagram": "",
        "model_source": "ai-h1"
      }
    ]
