        "marks": 6,
        "model": "Credit buying allows consumers to obtain goods immediately while spreading payments over time, enabling purchase of items that might otherwise be unaffordable. The consumer receives goods before payment is complete. Advantages include: immediate access to goods; spreading cost over manageable payments; enabling purchase during emergencies; allowing advantages of sales promotions. Disadvantages include: total cost is higher due to interest charges; consumer incurs debt; risk of financial difficulty if unable to pay; danger of over-indebtedness; interest charges represent additional expense. The Consumer Credit Act (1995) regulates credit agreements, requiring disclosure of annual percentage rate (APR), terms and conditions, total cost of credit and provision of a 10-day cooling-off period during which consumers can withdraw without penalty.",
