        "question": "State two benefits of the Small Claims Procedure",
        "marks": 6,
        "model": "A renewable resource is one that can be replenished naturally or through human management, ensuring continuous supply. Renewable resources include: wind power harnessed through wind turbines for electricity generation; solar power from sun rays converted to energy; water through hydroelectric power generation or direct use; biomass from plant materials used for energy; forests managed through replanting and conservation; fish stocks managed through sustainable fishing practices; geothermal energy from earth's internal heat. Renewable resources provide sustainable alternatives to fossil fuels, reducing environmental damage.",
