        "marks": 38,
        "model": "Textiles and Fashion design involves understanding fabric composition, properties and appropriate applications. Natural fibres include: cotton (breathable, absorbent, comfortable, washable but prone to wrinkling); wool (warm, insulating, elastic, water-resistant, but can shrink); silk (lustrous, strong despite fineness, drapes well, more delicate); linen (strong, absorbent, cool, wrinkles easily); other plant and animal fibres. Synthetic fibres include: polyester (durable, easy-care, quick-drying, wrinkle-resistant, versatile); nylon (strong, elastic, easy-care, lustrous); acrylic (warm, washable, resists pilling); other synthetics. Fabric properties determine suitability for specific purposes: durability for upholstery and workwear; comfort and breathability for summer clothing; insulation and elasticity for active wear; aesthetic properties including drape, lustre and texture for formal wear. Fashion design considers body proportions, colour, pattern and garment construction techniques. Current fashion trends reflect social values, sustainability concerns and technological innovations. Personal style choices are influenced by cultural background, age, socioeconomic status and individual preferences. Understanding textile and fashion principles enables informed clothing choices balancing aesthetics, function and sustainability.",
