        "model": "Personal economic management involves budgeting, saving, credit use and financial planning. Budgeting: tracking income and expenditure; identifying fixed costs (housing, utilities); managing variable costs (food, transport); allocating surplus to savings and discretionary spending; adjusting spending if expenses exceed income. Emergency savings: providing security against unexpected costs (medical emergencies, job loss, car repair); typically 3-6 months expenses; reduces need for high-interest borrowing. Saving strategies: automatic transfers to savings accounts; reducing discretionary spending; using savings accounts with attractive interest rates; avoiding impulse purchases; prioritizing long-term goals. Credit use: borrowing for major purchases (housing mortgages, vehicle loans); understanding credit terms including interest rates and repayment periods; assessing affordability before borrowing; maintaining good credit history; avoiding high-interest debt (credit cards, payday loans) when possible. Financial planning: setting long-term goals (education, house purchase, retirement); assessing income and expenditure over time; adjusting plans as circumstances change; seeking professional advice if needed. Financial literacy enables informed decisions and reduces vulnerability to exploitation. Socioeconomic factors significantly affect ability to save and invest: low-income individuals struggle with basic needs before saving; geographic and employment limitations affect earning potential. Supporting equitable access to financial services and education improves economic security and reduces inequality.",
