        "question": "Using the information provided in the chart, and having regard to current healthy eating guidelines, suggest three ways that the food sources of carbohydrates in the diet should be adjusted. Give a reason for each suggestion",
        "marks": 18,
        "model": "Reduce confectionary source and increase fruit and nut source as confectionary is high in sugar whereas fruit and vegetables are high in vitamins and fibre. Reduce cakes and biscuits source and increase bread source, as cakes and biscuits are high in sugar and fats whereas bread has less fat no sugar and could be a source of fibre. Increase breakfast cereals and reduce others, Breakfast cereals are generally fortified with Vitamins and mineral and they could also provide a source of fibre. Increase potatoes as potatoes are high in fibre and Vitamins A,B and C. Increase Milk and yogurt, Milk and yogurt contain high biological protein and Calcium. Add in pasta and rice in the others category as pasta and rice are a rich source of vitamin B and starch and are low in fat etc.",
