        "label": "B2a",
        "question": "Using the information in the table, comment on: (i) the effects of freezing on the Vitamin C content of peas (ii) the effects of canning on the Vitamin C, the Sodium and the Thiamine content of peas. Give one possible reason in each case",
        "marks": 24,
        "model": "Effects of freezing on Vit. C content – From the chart above the Vit C content has been Reduced from 25mg. in fresh peas to 17mg. in frozen peas. Possible reason – Vit C is a water soluble Vitamin and is unstable to high temps. A high temperature of water is a requirement for blanching. Effects of canning on Vit C content – From chart above the Vit C content has been from 25mg. to 8mg. Possible reason – Extremely high temperatures and processing times are needed for the canning process. Effects of canning on the Sodium content of peas – From the chart above the Sodium content has increased from 1mg. to 230mg. Possible reason – Large amounts of salt is used in the canning process. Effects of canning on the Thiamine content of peas – From the chart above the Thiamine content has been reduced from 32mg. to 13mg. Possible reason – the Vit. B group which includes Thiamine are unstable to high temperatures involved in canning",
