        "question": "Part (a)",
        "marks": 4,
        "model": "(a)(i) Three differences in eating habits between males and females: males consume more fried foods (over 40% more than 4 times weekly versus females approximately 30%); females consume more fruit and vegetables with approximately 40% eating 4+ servings versus males around 30%; males show higher consumption of just 2 or fewer protein servings (approximately 55% versus females 45%). (ii) Females have a healthier diet overall because they meet recommended guidelines for fruit and vegetable consumption more frequently, consuming more of these nutrient-dense foods which provide essential vitamins, minerals and dietary fibre. They consume less fried food which reduces saturated fat intake and associated cardiovascular disease risk. Higher protein awareness is demonstrated by lower percentages meeting inadequate intake levels. (b) Three servings daily from the milk, cheese and yoghurt group is recommended because dairy products are the primary source of bioavailable calcium essential for bone and teeth development and maintenance throughout life, particularly critical during adolescence and for preventing osteoporosis in later life. Dairy products also provide high-quality protein necessary for growth and tissue repair, and B vitamins including B12 for energy metabolism. (c) Protein composition includes amino acids linked by peptide bonds in various combinations. Functions include growth and repair of body tissues, production of enzymes and hormones, immune function through antibody production, and energy provision. Properties include solubility variation depending on structure, denaturation at high temperatures or extreme pH, and amino acid sequence determining protein specificity. (d) Four waste management strategies: selecting loose fresh produce rather than pre-packaged items to reduce packaging waste; choosing products with minimal or recyclable packaging; buying seasonal and locally-produced foods requiring less transportation packaging; and selecting bulk items to reduce individual product packaging.",
