        "question": "Extended response question on food preparation",
        "marks": 50,
        "model": "(a) Types of microwave cookers available include standard countertop models for basic reheating and cooking, combination microwave-convection ovens offering both microwave speed and conventional baking capability, and professional commercial microwaves with higher power output. Key selection factors: size to fit kitchen space and family needs, power wattage (typically 700-1000W for household use) affecting cooking speed, interior capacity for dish accommodation, and special features like sensor cooking, defrost programs, and child-safe lockouts. Usage guidelines include: never operating the oven empty, arranging food evenly for uniform heating, using microwave-safe containers (not metal), stirring food during cooking, and allowing standing time after cooking for heat distribution. Modern features include convection heating, steam combination cooking, programmable memory, inverter technology for even defrosting, and smart connectivity for remote operation. (b) The Sale of Goods and Supply of Services Act (1980) protects consumer interests by ensuring goods are of merchantable quality, fit for purpose, as described in advertising, and durable for reasonable periods. Sellers must provide clear product descriptions, accept responsibility for defects appearing within reasonable timeframes, and allow consumer redress through replacement or refund if goods are faulty or misrepresented.",
