      {
        "label": "B4",
        "question": "Extended response question on budgeting",
        "marks": 50,
        "model": "Four factors affecting consumer decision-making: (i) Advertising influences consumers through persuasive messaging, celebrity endorsements, and emotional appeals that create brand loyalty and desire for products; (ii) Household income determines purchasing power and influences choice between budget and premium products, affecting quality and quantity of purchases; (iii) Discount offers and promotional pricing encourage impulse purchases and switching between brands, particularly influencing purchasing decisions during sales periods; (iv) Shopper loyalty schemes provide rewards and incentives that encourage repeated purchases at specific retailers through point accumulation and exclusive discounts. Advantages of mail order shopping: convenience of shopping from home with home delivery, wider product selection from national suppliers, ability to return items easily, often with special offers for mail order. Disadvantages: inability to inspect items before purchase affecting quality assessment, delivery delays, return postage costs, and risk of items being damaged during delivery. Internet shopping advantages include 24/7 access, price comparison across multiple retailers, immediate availability of stock information, and often lower prices than physical stores. Disadvantages include security concerns with online payment, identity theft risks, lack of personal interaction with customer service, and environmental impact from packaging and delivery.",
        "diagram": "",
        "model_source": "ai-h1"
      }
