        "label": "B5",
        "question": "Extended response question on family and wellbeing",
        "marks": 50,
        "model": "(a)(i) Two factors outside the family influencing teenage behaviour: peer pressure from friends regarding appearance, behaviour, and risk-taking activities which often conflictwith parental values; media influence through television, film, social media and online content portraying behaviours and values that teenagers may emulate or aspire towards. (ii) Three aspects causing conflict: rebellion against authority and questioning parental rules as teenagers seek independence and autonomy; risk-taking behaviours including experimentation with substances or dangerous activities due to adolescent brain development affecting impulse control; emotional volatility and mood swings caused by hormonal changes creating friction with family members. Three ways to manage conflict: establishing clear, consistent boundaries while explaining the reasoning to help teenagers understand expectations; maintaining open communication with active listening to their concerns and perspectives rather than dismissive responses; involving teenagers in family decision-making to foster responsibility and feel valued as growing individuals. (c) One important teenage role is as household contributor with responsibilities to: help with domestic tasks such as cooking, cleaning, and laundry, demonstrating time management and responsibility skills; maintain personal hygiene and care for their own belongings, learning self-discipline and independence necessary for adult life.",
