        "question": "Elective 3: Social Studies",
        "marks": 80,
        "model": "(a)(i) At risk of poverty (relative poverty) is defined as having income below 60% of the national median income, making it difficult to participate in normal social and economic activities that most people in society can afford. This measurement reflects inequality within society rather than absolute deprivation. (ii) Four reasons for 14.4% at-risk poverty in 2008: unemployment and irregular employment patterns leaving families with unstable or insufficient income; low wages in certain sectors preventing workers from earning above poverty threshold; single-parent families often depending on one income struggling to cover childcare and living costs; structural economic factors and limited educational opportunities restricting access to well-paid employment. (iii) Two groups most at risk of consistent poverty: long-term unemployed persons facing barriers to re-employment and dwindling savings, affecting physical and mental health; lone parents struggling to balance childcare and employment, facing income inadequacy and social exclusion. Poverty effects include poor nutrition and health outcomes, reduced educational opportunities for children, social isolation and mental health issues, and decreased life expectancy. (b) Leisure serves essential functions including stress relief and mental health maintenance through activities away from work demands, physical health promotion through active recreation, and opportunity for family bonding and social relationships. Children benefit from leisure activities through physical development via sports and outdoor play, cognitive development through creative play and exploration, and emotional wellbeing from enjoyment and achievement.",
