        "model": "Carbohydrates are organic compounds composed of carbon, hydrogen, and oxygen providing primary energy for the body. Simple carbohydrates (monosaccharides and disaccharides) taste sweet, dissolve in water, provide quick energy but cause blood sugar spikes. Complex carbohydrates (polysaccharides) including starch and cellulose provide sustained energy and nutritional benefits. Starch from grains, potatoes, and legumes provides energy and B vitamins. Fibre aids digestion and prevents constipation. Functions include providing energy for body activities, sparing protein from oxidation enabling growth and repair, and providing roughage promoting digestive health. Maillard reaction during cooking browns food creating appealing colours. Gelatinisation when heated causes starch granules to swell thickening liquids. Caramelisation converts sugars to brown compounds. Dextrinisation converts starch to brown dextrins. Healthy guidelines recommend carbohydrates comprise 50% of daily calories from wholegrains with limited simple sugars. Carbohydrate quality affects health; high-fibre carbohydrates reduce heart disease and diabetes risk. Adequate consumption provides energy for activity and brain function; deficiency impairs performance.",
