        "marks": 40,
        "model": "Food choice is influenced by taste preferences, cultural and religious backgrounds, family eating patterns, and food availability. Nutritional knowledge, health conditions, allergies, cost, and ethical beliefs including vegetarianism influence choices. Balancing preferences with nutritional needs enables enjoyable healthy eating. Meal planning weekly ensures balanced nutrition across food groups. Breakfast should include protein, carbohydrates, and fruit for sustained energy. Lunch and dinner balance carbohydrates, protein, vegetables, and limited fat. Snacks should complement meals providing nutrients without excess calories. Shopping lists prevent impulse purchases controlling costs. Buying seasonal fresh produce and bulk items reduces expenses. Understanding food groups and nutrients enables selecting varied foods meeting needs. Cultural meals incorporating family traditions can be nutritionally balanced. Preparing meals at home enables ingredient control and cost savings versus takeaway foods. Food labels provide nutritional information supporting informed choices. Understanding meal planning enables healthy affordable family nutrition.",
