        "marks": 40,
        "model": "(i) For office work with public contact, I would wear tailored navy trousers with a cream blouse tucked in, a fitted blazer, and flat professional shoes. This creates a smart, approachable appearance suitable for client-facing work. (ii) Comfort is achieved through breathable natural fibres like cotton blends and well-fitted garments that allow movement without restriction. Aesthetic appeal is created through coordinated neutral colours, clean lines, and quality fabrics that appear professional and polished. Current fashion trends are reflected through contemporary silhouettes such as fitted tailoring rather than overly loose styles, minimal accessories, and classic styling that remains timeless. (iii) A fabric like a cotton-polyester blend is ideal because it combines the breathability and comfort of cotton with the durability and easy-care properties of polyester, essential for frequent wear in a professional setting. Alternatively, a fine linen blend would provide professional appearance with natural breathability required for all-day comfort in an office environment.",
