        "label": "C3",
        "question": "Elective 3: Social Studies question",
        "marks": 80,
        "model": "(a)(i) Social and economic change has profoundly affected family life. Changing attitudes to marriage have seen increased rates of cohabitation before marriage, later marriage ages, and higher divorce rates, reflecting reduced social stigma and greater personal autonomy. Traditional gender roles within the family have shifted dramatically with women increasingly pursuing careers, resulting in more egalitarian partnerships where household duties and child-rearing are shared responsibilities rather than exclusively female roles. Employment opportunities have expanded for women and changed work patterns for families, with more dual-income households and increased emphasis on flexible working arrangements. Improvements in education provision have raised educational aspirations and achievement levels, particularly for girls, changing family dynamics as educated children pursue independent careers and may relocate for opportunities, altering traditional family structure and intergenerational support systems. (ii) Three payments from the Department of Social and Family Affairs: Children's Allowance which provides monthly payments to parents or guardians for dependent children until age 16, or 18 if in approved education; Maternity Benefit which supports working mothers around childbirth; and One-Parent Family Payment which provides financial support to lone parents with dependent children to help with living costs and childcare.",
