        "marks": 6,
        "model": "(i) Smoke point is the temperature at which an oil or fat begins to smoke and break down, releasing harmful free radicals and acrolein vapour. It is important in cooking as oils with high smoke points are suitable for high-temperature cooking methods like frying, while those with low smoke points are better for dressings and low-temperature use. (ii) Flash point is the temperature at which an oil or fat is heated to the point where it can ignite spontaneously, creating a fire hazard. It is a critical safety consideration in food preparation and storage, determining safe handling and temperature limits during cooking.",
