        "marks": 6,
        "model": "HEAT TRANSFER IN COOKING - CONDUCTION: Transfer of heat from one food molecule to the next through direct contact and vibration. The cooker heats the pan, which transfers heat to the cooking liquid or fat, which then heats the food. Example: frying food in a hot pan. CONVECTION: Heat transfer through movement of hot liquid or air currents. Hot air rises when heated and falls when cooling, creating convection currents. Example: heating water in a pot - hot water rises from the bottom and cooler water sinks. RADIATION: Heat transfer through electromagnetic waves without requiring a medium. Example: grilling where heat radiates directly to the food from above.",
