        "question": "Part (a)",
        "marks": 2,
        "model": "ADVERTISING EFFECTS ON CONSUMER BEHAVIOUR: Advertising creates awareness of products and brands. It generates consumer interest and creates perceived needs. Product placement and shelf positioning influence purchasing decisions. Advertising techniques such as celebrity endorsements, humour, music and emotional appeals persuade consumers. Food samples provide direct experience. Colour, packaging and visual design attract attention. Advertising reinforces brand loyalty and repeat purchases. Target demographics receive tailored messages. Successful advertising leads to increased consumption even when products are not essential. Critical evaluation of advertising claims helps consumers make informed choices.",
