        "model": "TAX CREDIT: Reduces the amount of income tax a person has to pay. Income tax is calculated on gross income and then tax credits are deducted to arrive at the actual tax payable. The Revenue Commissioners issue annual notification of tax credits and standard cut-off points to each employee. Tax credits provide relief for various circumstances like dependent children or medical expenses. USC (UNIVERSAL SOCIAL CHARGE): Compulsory tax payable on gross income. Paid before pension contributions are deducted. Calculated as a percentage of total income, ranging from 1-8%. Employees are liable to pay USC if gross income exceeds €13,000 annually. Those earning less than €13,000 are exempt. USC replaced the former health levy and income levy systems.",
