    "id": "home-economics-pp-2016-HI-Elective1",
    "subject": "home-economics",
    "chapterId": "hom-nutrition-nutrients",
    "sectionId": "hom-section-c",
    "source": "LC Home-economics Higher 2016 — Elective1",
